<script lang="ts">
 import { onMount } from 'svelte'; import MetricCard from '$lib/components/MetricCard.svelte'; import PageHeader from '$lib/components/PageHeader.svelte'; import { listProjects } from '$lib/api/projects'; import type { ProjectView } from '$lib/api/types'; let projects=$state<ProjectView[]>([]),loading=$state(true),errorMessage=$state(''); onMount(async()=>{try{projects=(await listProjects(1,6)).data.items}catch(e){errorMessage=e instanceof Error?e.message:'项目概览加载失败'}finally{loading=false}}); const archivedCount=$derived(projects.filter(p=>p.archived_at).length);
</script>
<PageHeader title="项目总览" eyebrow="Workspace" description="按部门、项目、任务和操作日志组织内部项目管理。" actionHref="/projects/new" actionLabel="新建项目" /><div class="dashboard-grid"><MetricCard label="可见项目" value={String(projects.length)} hint="按当前账号权限过滤" /><MetricCard label="已归档项目" value={String(archivedCount)} hint="归档不等于删除" /><MetricCard label="任务编号种子" value={String(projects.reduce((sum,p)=>sum+p.task_number_seed,0))} hint="各项目独立递增" /><MetricCard label="分页上限" value="100" hint="任务列表单页最大条数" /></div>{#if errorMessage}<section class="workspace-card error-state">{errorMessage}</section>{:else if loading}<section class="workspace-card state-box">正在加载近期项目…</section>{:else}<section class="workspace-card"><h2>近期项目</h2>{#each projects as project}<div class="project-row"><strong>{project.project_key}</strong><span>{project.name} · {project.archived_at?'已归档':'活跃'}</span><a href={`/projects/${project.project_key}`}>进入</a></div>{:else}<p class="empty-inline">当前账号还没有可见项目。</p>{/each}</section>{/if}
<style>.dashboard-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:18px}.project-row{display:grid;grid-template-columns:150px 1fr auto;gap:12px;padding:14px 0;border-top:1px solid var(--color-border)}.project-row span{color:var(--color-text-muted)}.project-row a{color:var(--color-primary);font-weight:700}.error-state{color:var(--color-danger)}.state-box{text-align:center;color:var(--color-text-muted)}@media(max-width:1024px){.dashboard-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:640px){.dashboard-grid,.project-row{grid-template-columns:1fr}}</style>
